def extract(tree):
    rows = tree.where(content_desc="sourceLanguagePicker")
    if not rows:
        raise ValueError("Source language picker is absent")
    name = rows[0]["name"]
    if ": " not in name:
        raise ValueError("Source language is not reported by the picker")
    return name.split(": ", 1)[1]

def extract(tree):
    rows = tree.where(content_desc="targetLanguagePicker")
    if not rows:
        raise ValueError("Destination language picker is absent")
    name = rows[0]["name"]
    if ": " not in name:
        raise ValueError("Destination language is not reported by the picker")
    return name.split(": ", 1)[1]

