    status = rows[0]["text"] or ""
    return "Translation failed" not in status

def extract(tree):
    rows = tree.where(content_desc="statusLabel")
    if not rows:
        raise ValueError("Translation status is absent")
    status = (rows[0]["text"] or "").lower()
    return "apple intelligence" in status and ("using" in status or "powered by" in status or "translated by" in status)

